#include <cstddef>
#include <algorithm>
class IntVector {
    int* data_ = nullptr;
    std::size_t size_ = 0, cap_ = 0;
    void grow() {
        std::size_t nc = cap_ ? cap_ * 2 : 4;
        int* nd = new int[nc];
        for (std::size_t i = 0; i < size_; ++i) nd[i] = data_[i];
        delete[] data_; data_ = nd; cap_ = nc;
    }
public:
    IntVector() = default;
    ~IntVector() { delete[] data_; }
    IntVector(const IntVector& o) : size_(o.size_), cap_(o.cap_) {
        data_ = cap_ ? new int[cap_] : nullptr;
        for (std::size_t i = 0; i < size_; ++i) data_[i] = o.data_[i];
    }
    IntVector& operator=(const IntVector& o) {
        if (this != &o) { IntVector tmp(o); std::swap(data_, tmp.data_); std::swap(size_, tmp.size_); std::swap(cap_, tmp.cap_); }
        return *this;
    }
    void push_back(int x) { if (size_ == cap_) grow(); data_[size_++] = x; }
    std::size_t size() const { return size_; }
    int operator[](int i) const { return data_[i]; }
};

