#include <vector>
#include <thread>
long long concurrent_sum(const std::vector<int>& v, int threads) {
    if (v.empty()) return 0;
    if (threads < 1) threads = 1;
    if (threads > (int)v.size()) threads = v.size();
    std::vector<long long> partial(threads, 0);
    std::vector<std::thread> pool;
    size_t chunk = (v.size() + threads - 1) / threads;
    for (int t = 0; t < threads; ++t) {
        size_t lo = t * chunk, hi = std::min(v.size(), lo + chunk);
        pool.emplace_back([&, lo, hi, t]{ long long s=0; for (size_t i=lo;i<hi;++i) s+=v[i]; partial[t]=s; });
    }
    for (auto& th : pool) th.join();
    long long total = 0; for (long long p : partial) total += p; return total;
}

