void sort_by_frequency(std::vector<int>& v) {
    std::map<int,int> freq;
    for (int x : v) freq[x]++;
    std::stable_sort(v.begin(), v.end(), [&](int a, int b){
        if (freq[a] != freq[b]) return freq[a] > freq[b];
        return a < b;
    });
}

